'use strict';
const $=s=>document.querySelector(s),START=8,END=24,TZ='Europe/Warsaw';
function unit(){return innerWidth<700?innerWidth/576:1;}
function hourSize(){return 88*unit();}
const weekdays=['pn','wt','śr','czw','pt'],months=['sty','lut','mar','kwi','maj','cze','lip','sie','wrz','paź','lis','gru'];
const lessons=[
 {name:'Język polski',start:'08:35',end:'09:20',room:'213'},
 {name:'Język polski',start:'09:25',end:'10:10',room:'213'},
 {name:'Edukacja zdrowotna',start:'10:20',end:'11:05',room:'101'},
 {name:'Biologia',start:'11:20',end:'12:05',room:'212'},
 {name:'Zajęcia z wychowawcą',start:'12:15',end:'13:00',room:'212'},
 {name:'Wychowanie fizyczne',start:'13:20',end:'14:05',room:'sg3'},
 {name:'Język hiszpański',start:'14:15',end:'15:00',room:'304'},
 {name:'Język angielski',start:'15:05',end:'15:50',room:'140'},
 {name:'IPM9JM1 - BHP w ekspotacji urządzeń techniki komputerowej',start:null,end:null,room:null}
];
function warsawNow(date=new Date()) {const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).map(x=>[x.type,x.value]));return {key:`${p.year}-${p.month}-${p.day}`,date:new Date(+p.year,+p.month-1,+p.day,12),minute:+p.hour*60 + +p.minute + +p.second/60};}
function key(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function plus(d,n){let a=new Date(d);a.setDate(a.getDate()+n);return a;}
function monday(d){return plus(d,-((d.getDay()+6)%7));}
function minutes(s){const [h,m]=s.split(':').map(Number);return h*60+m;}
function position(m){return (30+(m-START*60)*88/60)*unit();}
function completed(day,end,now){return !!end&&(day<now.key||(day===now.key&&minutes(end)<=now.minute));}
let current=warsawNow(),selected=current.date.getDay()===0?plus(current.date,1):current.date.getDay()===6?plus(current.date,2):current.date,weekStart=monday(selected),view='day';
function header(){const now=warsawNow();$('#month').textContent=months[weekStart.getMonth()];$('#month').title=weekStart.getFullYear();$('#days').replaceChildren();for(let i=0;i<5;i++){const date=plus(weekStart,i),button=document.createElement('button');button.className='date'+(key(date)===key(selected)?' selected':'')+(key(date)===now.key?' today':'');button.setAttribute('aria-label',date.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}));button.setAttribute('aria-pressed',String(key(date)===key(selected)));button.innerHTML=`<span class="weekday">${weekdays[i]}</span><span class="number">${date.getDate()}</span>`;button.onclick=()=>{selected=date;render(true);};$('#days').append(button);}$('#day').setAttribute('aria-selected',String(view==='day'));$('#week').setAttribute('aria-selected',String(view==='week'));}
function makeTimeline(date,isWeek){const line=document.createElement('div');line.className='timeline';for(let h=START;h<END;h++){const hour=document.createElement('div');hour.className='hour';hour.style.top=position(h*60)+'px';if(!isWeek){const label=document.createElement('span');label.textContent=String(h).padStart(2,'0')+':00';hour.append(label);}line.append(hour);}const day=key(date),now=warsawNow();if(date.getDay()===2){for(const lesson of lessons.filter(x=>x.start)){const node=document.createElement('div');node.className='lesson';node.dataset.end=lesson.end;node.dataset.day=day;node.style.top=position(minutes(lesson.start))+'px';node.style.height=(minutes(lesson.end)-minutes(lesson.start))*hourSize()/60+'px';const title=document.createElement('div');title.className='subject';title.textContent=lesson.name;const dot=document.createElement('span');dot.className='dot';dot.hidden=!completed(day,lesson.end,now);dot.setAttribute('aria-label','Lekcja zakończona');title.append(dot);const details=document.createElement('div');details.className='details';details.textContent=`${lesson.start}–${lesson.end}, Sala ${lesson.room}`;node.append(title,details);line.append(node);}}else{const empty=document.createElement('div');empty.className='empty';empty.textContent='Brak danych';line.append(empty);}const marker=document.createElement('div');marker.className='now';marker.dataset.day=day;marker.setAttribute('aria-label','Aktualna godzina');line.append(marker);return line;}
function untimed(date){if(date.getDay()!==2)return null;const node=document.createElement('div');node.className='untimed';const title=document.createElement('div');title.className='subject';title.textContent=lessons[8].name;const details=document.createElement('div');details.className='details';details.textContent='Godzina niepodana';node.append(title,details);return node;}
function tick(){const now=warsawNow();document.querySelectorAll('.now').forEach(line=>{line.hidden=line.dataset.day!==now.key||now.minute<START*60;line.style.top=position(now.minute)+'px';});document.querySelectorAll('.lesson').forEach(node=>{node.querySelector('.dot').hidden=!completed(node.dataset.day,node.dataset.end,now);});if(current.key!==now.key){current=now;header();}}
function render(scroll){header();const container=$('#calendar');container.replaceChildren();container.className=view==='week'?'weekly':'';if(view==='day'){container.append(makeTimeline(selected,false));const extra=untimed(selected);if(extra)container.append(extra);}else{const grid=document.createElement('div');grid.className='week-grid';const gutter=document.createElement('div');gutter.className='time-gutter';for(let h=START;h<END;h++){const label=document.createElement('span');label.textContent=String(h).padStart(2,'0')+':00';label.style.top=position(h*60)+'px';gutter.append(label);}grid.append(gutter);for(let i=0;i<5;i++){const date=plus(weekStart,i),column=document.createElement('div');column.className='week-column';column.append(makeTimeline(date,true));const extra=untimed(date);if(extra)column.append(extra);grid.append(column);}container.append(grid);}tick();if(scroll){$('#scroll').scrollTop=0;$('#scroll').scrollLeft=view==='week'?Math.max(0,((selected.getDay()+6)%7)*140-45):0;}}
$('#day').onclick=()=>{view='day';render(true);};$('#week').onclick=()=>{view='week';render(true);};$('#previous').onclick=()=>{weekStart=plus(weekStart,-7);selected=plus(selected,-7);render(true);};$('#next').onclick=()=>{weekStart=plus(weekStart,7);selected=plus(selected,7);render(true);};setInterval(tick,15000);addEventListener('resize',()=>render(false));document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});render(true);
